"use strict";

function resultsCore(base) {
  if (base.id !== 'appK9IX59jFwUkB2u') throw Error('Wrong Results base');
  const cell = (r, field) => r.getCellValue(field);
  const text = (r, field) => String(cell(r, field) ?? '').trim();
  const parse = value => value ? JSON.parse(value) : {};
  const read = async name => (await base.getTable(name).selectRecordsAsync()).records;
  const equal = (a, b) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null);
  const nonzero = v => v !== null && v !== undefined && typeof v !== 'boolean' && String(v).trim() !== '' && Number.isFinite(Number(v)) && Number(v) !== 0;
  const yFields = ['score1', 'time-one', 'faults-one', 'time-fault-one'];
  const xFields = [...Array.from({length: 6}, (_, i) => 'score' + (i + 1)),
    ...['time', 'faults', 'time-fault'].flatMap(n => ['one', 'two', 'three'].map(p => n + '-' + p)),
    'placing', 'position', 'points-earned', 'prize-money'];
  const instances = (records, fields) => records.map(r => ({record: r.id, key: text(r, 'result-key'),
    values: Object.fromEntries(fields.filter(f => nonzero(cell(r, f))).map(f => [f, cell(r, f)])),
    observedAt: cell(r, 'last-success') || null})).filter(r => Object.keys(r.values).length).sort((a, b) => a.record.localeCompare(b.record));
  const content = instances => JSON.stringify(instances.map(({observedAt, ...r}) => r));
  async function write(name, id, fields) {
    const t = base.getTable(name);
    if (id) await t.updateRecordAsync(id, fields); else id = await t.createRecordAsync(fields);
    const saved = await t.selectRecordAsync(id);
    const normalize = v => v === '' || v === false || v === undefined ? null : v;
    const comparable = v => Array.isArray(v) ? v.map(x => x && typeof x === 'object' && 'id' in x ? {id: x.id} : x) : v && typeof v === 'object' && 'name' in v ? {name: v.name} : normalize(v);
    if (!saved || Object.entries(fields).some(([k, v]) => !equal(comparable(cell(saved, k)), comparable(v)))) throw Error('Results write readback mismatch: ' + name);
    return saved;
  }
  async function save(rows, key, fields) {
    const found = rows.filter(r => text(r, 'snapshot-key') === key);
    if (found.length > 1) {
      for (const r of found) await write('snapshot', r.id, {'check-status': 'Conflict', 'check-reason': 'Duplicate snapshot-key'});
      throw Error('Duplicate snapshot-key: ' + key);
    }
    const old = found[0];
    const delta = Object.fromEntries(Object.entries(fields).filter(([f, v]) => !old || !equal(cell(old, f) ?? null, v === '' || v === false ? null : v)));
    if (old && !Object.keys(delta).length) return old;
    const saved = await write('snapshot', old?.id, old ? delta : {'snapshot-key': key, ...fields});
    if (old) rows[rows.indexOf(old)] = saved; else rows.push(saved);
    return saved;
  }
  const dayKey = tripKey => tripKey.split('|').slice(0, 3).join('|');
  const eligible = (key, days) => days.some(d => text(d, 'show-day-key') === dayKey(key) && cell(d, 'day-priority') === 0);
  const scope = key => {const p = key.split('|'); if (p.length !== 7 || !p.slice(0, 2).every(s => /^\d+$/.test(s))) throw Error('Invalid trip-key'); return {'customer-id': Number(p[0]), 'show-id': Number(p[1]), date: p[2], 'ring-number': Number(p[3]), 'class-id': Number(p[4])};};
  return {cell, text, parse, read, equal, nonzero, yFields, xFields, instances, content, write, save, dayKey, eligible, scope};
}

async function resultsLogged(base, operation, action) {
  const C = typeof resultsCore === 'function' ? resultsCore(base) : require('./event-core').resultsCore(base);
  const started = new Date().toISOString(), runId = 'events|' + started + '|' + Math.random().toString(36).slice(2);
  // Persist the running state before work so failed logging cannot look like completion.
  const run = await C.write('run-logs', null, {'run-id': runId, started, result: 'Running'});
  let report, failure;
  try { report = await action(); } catch (e) { failure = e; }
  const completed = new Date().toISOString(), result = failure ? 'Failed' : 'Complete';
  const summary = JSON.stringify({operation, ...(report || {}), ...(failure ? {error: String(failure.message)} : {})});
  if (failure) await C.write('errs-log', null, {'error-key': runId, 'run-id': runId, 'occurred-at': completed, message: String(failure.message)});
  await C.write('run-logs', run.id, {completed, result, summary, ...(report?.showId ? {'show-id': report.showId} : {})});
  const beats = (await C.read('heartbeat')).filter(r => C.text(r, 'heartbeat-key') === 'events|' + operation);
  if (beats.length > 1) throw Error('Duplicate Results heartbeat');
  await C.write('heartbeat', beats[0]?.id, {'heartbeat-key': 'events|' + operation, 'run-id': runId, started, completed, 'checked-at': completed,
    result, summary, ...(!failure ? {'last-success': completed} : {})});
  if (failure) throw failure;
  return report;
}

if (typeof module !== 'undefined') module.exports = {resultsCore, resultsLogged};

"use strict";

async function resultsEvent(base, {source, recordId, now = new Date().toISOString(), reconcile = false} = {}) {
  const C = typeof resultsCore === 'function' ? resultsCore(base) : require('./event-core').resultsCore(base);
  const [trips, results, days, rows] = await Promise.all(['wef-data.trips', 'wef-data.results', 'w-days', 'snapshot'].map(C.read));
  let selected = trips;
  if (!reconcile) {
    if (!['wef-data.trips', 'wef-data.results'].includes(source)) throw Error('Unknown Results event source');
    const changed = (source === 'wef-data.trips' ? trips : results).find(r => r.id === recordId);
    if (!changed) throw Error('Results event source record missing');
    const key = C.text(changed, source === 'wef-data.trips' ? 'trip-key' : 'result-key');
    selected = trips.filter(t => C.text(t, 'trip-key') === key);
    if (!selected.length) throw Error('Matching trip not yet available');
  }
  const report = {created: 0, expected: 0, complete: 0, conflicts: 0};
  const handled = new Set();
  for (const trip of selected) {
    const key = C.text(trip, 'trip-key');
    if (handled.has(key) || !C.eligible(key, days)) continue;
    handled.add(key);
    const common = C.scope(key), parts = key.split('|');
    report.showId = common['show-id'];
    const raw = C.parse(C.cell(trip, 'source-json'));
    const identity = {tripKey: key, tripRecord: trip.id, entry: {key: C.text(trip, 'entry'), id: parts[5]},
      horse: {id: C.text(trip, 'horse'), name: raw.horse || ''}, rider: {id: C.text(trip, 'rider'), name: raw.rider_name || ''}};
    const matching = results.filter(r => C.text(r, 'result-key') === key);
    const issues = [];
    if (trips.filter(t => C.text(t, 'trip-key') === key).length > 1) issues.push('Duplicate source trip-key');
    if (days.filter(d => C.text(d, 'show-day-key') === C.dayKey(key) && C.cell(d, 'day-priority') === 0).length > 1) issues.push('Duplicate show-day');
    if (identity.entry.key !== parts[1] + '|' + parts[5] || String(raw.entry_id) !== parts[5]) issues.push('Entry identity conflict');
    if (!identity.horse.id || !identity.rider.id || String(raw.horse_id) !== identity.horse.id || String(raw.rider_id) !== identity.rider.id) issues.push('Horse/rider identity conflict');
    if (matching.some(r => C.text(r, 'class') !== C.text(trip, 'class') || C.text(r, 'entry') !== identity.entry.key ||
      (C.cell(r, 'trip') || []).length !== 1 || C.cell(r, 'trip')[0].id !== trip.id)) issues.push('Result identity conflict');
    // Multiple matching result instances are retained, not collapsed into one value.
    const x = C.instances(matching, C.xFields), y = C.instances(matching, C.yFields);
    for (const kind of ['Y', 'X']) {
      const actualKey = kind + '|' + key, expectedKey = 'expected|' + actualKey;
      const actual = rows.filter(r => C.text(r, 'snapshot-key') === actualKey);
      const expectations = rows.filter(r => C.text(r, 'snapshot-key') === expectedKey);
      const problems = [...issues];
      if (actual.length > 1 || expectations.length > 1) problems.push('Duplicate Results record');
      const prior = expectations[0] ? C.parse(C.cell(expectations[0], 'phase-json')) : {};
      const state = {...prior, recordType: 'expectation', trigger: kind};
      const verified = C.text(trip, 'class_related_data.results_verified (from class)') === '1';
      let qualifies = kind === 'X' && verified && x.length > 0;
      if (kind === 'Y') {
        if (!reconcile && C.text(trip, 'gone-in') === '1' && !state.listening && !actual.length) {
          state.listening = true; state.armedAt = now; state.baseline = C.content(y);
        } else if (!reconcile && source === 'wef-data.results' && state.listening && C.text(trip, 'gone-in') === '1') {
          qualifies = y.length > 0 && C.content(y) !== state.baseline;
        }
      }
      const payload = {identity, instances: kind === 'X' ? x : y};
      if (actual.length === 1) {
        const saved = C.parse(C.cell(actual[0], 'results-json'));
        // Y is the first-change receipt. Later scores are expected and never replace it.
        if (kind === 'X' && (!verified || !C.equal(saved.identity, identity) || C.content(saved.instances || []) !== C.content(x))) problems.push('Verified result changed');
        if (C.text(actual[0], 'check-status') === 'Conflict') problems.push(C.text(actual[0], 'check-reason'));
      }
      if (!reconcile && qualifies && !actual.length) {
        const saved = await C.save(rows, actualKey, {...common, finality: kind, 'check-status': problems.length ? 'Conflict' : 'Complete',
          'check-reason': problems.join('; ') || (kind === 'Y' ? 'First result change after gone-in' : 'Verified nonzero results'),
          'accepted-at': now, 'source-observed-at': C.text(trip, 'last-success'), 'results-verified': kind === 'X',
          'result-count': payload.instances.length, 'results-json': JSON.stringify(payload),
          'phase-json': JSON.stringify({recordType: 'result', trigger: kind}),
          'source-evidence-json': JSON.stringify({source, recordId, resultRecords: matching.map(r => r.id)})});
        actual.push(saved); report.created++;
      }
      if (problems.length) for (const r of actual) await C.write('snapshot', r.id, {'check-status': 'Conflict', 'check-reason': [...new Set(problems)].join('; ')});
      const status = problems.length ? 'Conflict' : actual.length === 1 ? 'Complete' : 'Expected';
      await C.save(rows, expectedKey, {...common, finality: kind, 'check-status': status,
        'check-reason': problems.length ? [...new Set(problems)].join('; ') : actual.length ? 'Result record read back: ' + actual[0].id : kind === 'Y' && state.listening ? 'Listening for first nonzero result change' : 'Awaiting source event',
        'results-json': JSON.stringify({identity}), 'phase-json': JSON.stringify(state)});
      report[status === 'Expected' ? 'expected' : status === 'Complete' ? 'complete' : 'conflicts']++;
    }
  }
  if (reconcile) for (const row of rows) {
    const key = C.text(row, 'snapshot-key').replace(/^expected\|/, '').replace(/^[XY]\|/, '');
    if (key.split('|').length === 7 && C.eligible(key, days) && !trips.some(t => C.text(t, 'trip-key') === key)) {
      await C.write('snapshot', row.id, {'check-status': 'Conflict', 'check-reason': 'Source trip missing'}); report.conflicts++;
    }
  }
  return report;
}

if (typeof module !== 'undefined') module.exports = {resultsEvent};

"use strict";

async function linkResults(base) {
  const C = typeof resultsCore === 'function' ? resultsCore(base) : require('./event-core').resultsCore(base);
  const [rows, shows, days, results, horses, riders] = await Promise.all(['snapshot', 'w-shows', 'w-days', 'wef-data.results', 'w-horses', 'w-riders'].map(C.read));
  const report = {linked: 0, unresolved: 0};
  for (const row of rows) {
    const key = C.text(row, 'snapshot-key');
    if (!/^(expected\|)?[XY]\|/.test(key)) continue;
    const payload = C.parse(C.cell(row, 'results-json')), identity = payload.identity;
    if (!identity?.tripKey) {report.unresolved++; continue;}
    const parts = identity.tripKey.split('|'), fields = {};
    const lookups = [
      ['w-shows', shows.filter(r => C.text(r, 'show-key') === parts.slice(0, 2).join('|')), true],
      ['w-days', days.filter(r => C.text(r, 'show-day-key') === parts.slice(0, 3).join('|')), true],
      ['wef-data.results', results.filter(r => C.text(r, 'result-key') === identity.tripKey), false],
      ['w-horses', horses.filter(r => C.text(r, 'horse-id') === identity.horse?.id), true],
      ['w-riders', riders.filter(r => C.text(r, 'rider-id') === identity.rider?.id), true]
    ];
    for (const [field, matches, single] of lookups) {
      if ((C.cell(row, field) || []).length) continue;
      if (!matches.length || (single && matches.length !== 1)) {report.unresolved++; continue;}
      fields[field] = matches.map(r => ({id: r.id}));
    }
    if (Object.keys(fields).length) {await C.write('snapshot', row.id, fields); report.linked++;}
  }
  return report;
}

if (typeof module !== 'undefined') module.exports = {linkResults};

"use strict";

async function cleanResults(base, {reason, now = new Date().toISOString()} = {}) {
  const C = typeof resultsCore === 'function' ? resultsCore(base) : require('./event-core').resultsCore(base);
  if (!['daily', 'cap', 'new-show'].includes(reason)) throw Error('Unknown Results cleanup');
  const today = new Intl.DateTimeFormat('en-CA', {timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit'}).format(new Date(now));
  const epoch = value => {const n = Date.parse(value); return Number.isFinite(n) ? n : null;};
  const oldTime = value => {const n = epoch(value); return n !== null && n <= Date.parse(now) && new Intl.DateTimeFormat('en-CA', {timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit'}).format(new Date(n)) < today;};
  const [controls, runs, errors, rows, shows, days] = await Promise.all(['cleanup', 'run-logs', 'errs-log', 'snapshot', 'w-shows', 'w-days'].map(C.read));
  const defaults = shows.filter(r => C.cell(r, 'is_default') === true);
  const defaultIds = new Set(defaults.map(r => C.cell(r, 'show_id')));
  const currentDays = new Set(days.filter(r => C.cell(r, 'day-priority') === 0).map(r => C.text(r, 'show-day-key')));
  // Logs carry show-id only: preserve the show when any of its days is protected.
  const currentShows = new Set([...currentDays].map(key => key.split('|')[1]));
  const terminal = r => ['Complete', 'Success', 'Failed'].includes(C.text(r, 'result')) && oldTime(C.text(r, 'completed'));
  // Delete only explicit owned tables. A checked source/reference row never grants deletion.
  const owned = {'errs-log': errors, 'run-logs': runs, snapshot: rows};
  const report = {reason, deleted: 0};
  for (const [name, records] of Object.entries(owned)) {
    const control = controls.filter(r => C.text(r, 'Name') === name);
    if (control.length !== 1 || C.cell(control[0], 'cleanup')?.name !== 'checked') continue;
    if (name === 'snapshot' && reason !== 'new-show') continue;
    if (reason === 'cap' && records.length <= 1000) continue;
    let eligible = records.filter(r => {
      if (name === 'snapshot') {
        const show = C.cell(r, 'show-id'), customer = C.cell(r, 'customer-id'), date = C.text(r, 'date');
        return defaults.length === 1 && show && !defaultIds.has(show) && shows.some(s => C.cell(s, 'show_id') === show && C.cell(s, 'customer_id') === customer) &&
          C.text(r, 'check-status') === 'Complete' && /^\d{4}-\d{2}-\d{2}$/.test(date) && date < today && !currentDays.has(customer + '|' + show + '|' + date);
      }
      const run = name === 'run-logs' ? r : runs.find(run => C.text(run, 'run-id') === C.text(r, 'run-id'));
      if (!run || !terminal(run)) return false;
      if (currentShows.has(C.text(run, 'show-id'))) return false;
      if (name === 'errs-log' && !oldTime(C.text(r, 'occurred-at'))) return false;
      if (reason === 'new-show') return defaults.length === 1 && C.cell(run, 'show-id') && !defaultIds.has(C.cell(run, 'show-id'));
      return true;
    });
    eligible.sort((a, b) => String(C.cell(a, name === 'snapshot' ? 'accepted-at' : name === 'errs-log' ? 'occurred-at' : 'completed') || '').localeCompare(String(C.cell(b, name === 'snapshot' ? 'accepted-at' : name === 'errs-log' ? 'occurred-at' : 'completed') || '')) || a.id.localeCompare(b.id));
    if (reason === 'cap') eligible = eligible.slice(0, 500);
    const started = new Date().toISOString();
    let deleted = 0;
    try {
      // Read back each delete batch. Never repeat an ambiguous deletion.
      for (let i = 0; i < eligible.length; i += 50) {
        const ids = eligible.slice(i, i + 50).map(r => r.id);
        await base.getTable(name).deleteRecordsAsync(ids);
        for (const id of ids) if (await base.getTable(name).selectRecordAsync(id)) throw Error('Cleanup delete readback mismatch');
        deleted += ids.length;
      }
      await C.write('cleanup', control[0].id, {records: records.length, started, completed: new Date().toISOString(), result: {name: 'Success'},
        'records-deleted': deleted, 'records-archived': 0, error: '', ...(reason === 'new-show' && defaults.length === 1 ? {'new-show-id': C.cell(defaults[0], 'show_id')} : {})});
    } catch (e) {
      await C.write('cleanup', control[0].id, {records: records.length, started, completed: new Date().toISOString(), result: null, 'records-deleted': deleted, error: String(e.message)});
      throw e;
    }
    report.deleted += deleted;
  }
  return report;
}

if (typeof module !== 'undefined') module.exports = {cleanResults};

const cfg = input.config();
await resultsLogged(base, cfg.operation, async () => {
  if (cfg.operation === 'event') {const result = await resultsEvent(base, cfg); await linkResults(base); return result;}
  if (cfg.operation === 'reconcile') {const result = await resultsEvent(base, {reconcile: true}); await linkResults(base); return result;}
  return cleanResults(base, {reason: cfg.operation});
});

"use strict";

function resultsCore(base) {
